func TestD48ConstantsWideLn10RoundsToD48Ln10(t *testing.T) {
	q := divPow10_q320res(u320_LN10_WIDE_COEFF, 42)
	rounded := q.quot()
	if q.residue >= RESIDUE_HALF {
		rounded = add_320_320x64(rounded, 1)
	}
	if rounded != d48_u320(d48_LN10) {
		t.Errorf("wide ln10 does not round to d48_LN10")
	}
	if LN10_WIDE_QEXP+42 != d48_qExp(d48_LN10) {
		t.Errorf("LN10_WIDE_QEXP + 42 != qExp(d48_LN10)")
	}
}
